import React, { createContext, useState, useEffect, useContext, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../services/apiService';
import io from 'socket.io-client';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [socket, setSocket] = useState(null);
  const [socketConnected, setSocketConnected] = useState(false);
  const [socketAuthenticated, setSocketAuthenticated] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const socketRef = useRef(null);
  const navigate = useNavigate();

  // Initialize WebSocket connection
  // Logout function with cleanup
  const logout = useCallback(() => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
    setIsAuthenticated(false);
    setSocketConnected(false);
    setSocketAuthenticated(false);
    if (socketRef.current) {
      socketRef.current.disconnect();
      socketRef.current = null;
    }
    setSocket(null);
    delete api.defaults.headers.common['Authorization'];
    toast.info('You have been logged out.');
    navigate('/login', { replace: true });
  }, [navigate]);

  // Initialize WebSocket connection
  const initWebSocket = useCallback((token) => {
    if (!token) {
      console.log('No token available for WebSocket connection');
      return null;
    }

    // If we already have a socket and it's connected, return it
    if (socketRef.current?.connected) {
      console.log('WebSocket already connected, reusing existing connection');
      return socketRef.current;
    }

    // Close existing socket if it exists
    if (socketRef.current) {
      console.log('Closing existing WebSocket connection');
      socketRef.current.off(); // Remove all event listeners
      socketRef.current.disconnect();
      socketRef.current = null;
    }
    
    // Prevent multiple connection attempts
    if (socketRef.current?.connecting) {
      console.log('WebSocket connection already in progress');
      return null;
    }

    console.log('Initializing new WebSocket connection with token:', token.substring(0, 10) + '...');
    
    try {
      const newSocket = io(process.env.REACT_APP_WS_URL || 'http://localhost:5000', {
        path: '/socket.io',
        transports: ['websocket', 'polling'],
        reconnection: false, // We'll handle reconnection manually
        timeout: 10000,
        auth: { token },
        withCredentials: true,
        autoConnect: true,
        forceNew: true,
        secure: process.env.NODE_ENV === 'production',
        rejectUnauthorized: false
      });

      let reconnectAttempts = 0;
      const maxReconnectAttempts = 5;
      let reconnectTimeout = null;

      const setupReconnection = () => {
        if (reconnectAttempts >= maxReconnectAttempts) {
          console.log('Max reconnection attempts reached');
          return;
        }

        const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000); // Exponential backoff, max 30s
        console.log(`Will attempt to reconnect in ${delay}ms (attempt ${reconnectAttempts + 1}/${maxReconnectAttempts})`);
        
        reconnectTimeout = setTimeout(() => {
          if (user && !newSocket.connected) {
            reconnectAttempts++;
            newSocket.connect();
          }
        }, delay);
      };

      // Set up event handlers
      const onConnect = () => {
        console.log('WebSocket connected with ID:', newSocket.id);
        setSocketConnected(true);
        reconnectAttempts = 0; // Reset reconnect attempts on successful connection
        
        // Clear any pending reconnection timeout
        if (reconnectTimeout) {
          clearTimeout(reconnectTimeout);
          reconnectTimeout = null;
        }
      };

      const onAuthenticated = (data) => {
        console.log('WebSocket authenticated successfully', data);
        setSocketAuthenticated(true);
        
        // Join user's personal room if user ID is available
        if (user?._id) {
          newSocket.emit('join', { userId: user._id });
        }
      };

      const onDisconnect = (reason) => {
        console.log('WebSocket disconnected. Reason:', reason);
        setSocketConnected(false);
        setSocketAuthenticated(false);
        
        // Only attempt to reconnect if user is still logged in and not already reconnecting
        if (user && !reconnectTimeout) {
          setupReconnection();
        }
      };

      const onConnectError = (error) => {
        console.error('WebSocket connection error:', error.message);
        setSocketConnected(false);
        setSocketAuthenticated(false);
        
        // For auth errors, clear the token and redirect to login
        if (error.message.includes('401') || error.message.includes('403')) {
          console.log('Authentication error, logging out...');
          logout();
        } else if (user) {
          setupReconnection();
        }
      };

      // Set up event listeners
      newSocket.on('connect', onConnect);
      newSocket.on('authenticated', onAuthenticated);
      newSocket.on('disconnect', onDisconnect);
      newSocket.on('connect_error', onConnectError);
      newSocket.on('error', (error) => {
        console.error('WebSocket error:', error);
      });

      // Cleanup function
      const cleanup = () => {
        if (reconnectTimeout) {
          clearTimeout(reconnectTimeout);
        }
        newSocket.off('connect', onConnect);
        newSocket.off('authenticated', onAuthenticated);
        newSocket.off('disconnect', onDisconnect);
        newSocket.off('connect_error', onConnectError);
      };

      // Store the socket reference and cleanup function
      socketRef.current = newSocket;
      socketRef.current.cleanup = cleanup;
      setSocket(newSocket);
      
      return newSocket;
      
    } catch (error) {
      console.error('Error initializing WebSocket:', error);
      return null;
    }
  }, [user, logout]);

  // Clean up WebSocket connection
  const cleanupWebSocket = useCallback(() => {
    if (socketRef.current) {
      console.log('Cleaning up WebSocket connection');
      if (socketRef.current.cleanup) {
        socketRef.current.cleanup();
      }
      socketRef.current.disconnect();
      socketRef.current = null;
      setSocket(null);
      setSocketConnected(false);
      setSocketAuthenticated(false);
    }
  }, []);

  // Check authentication status on mount
  useEffect(() => {
    let isMounted = true;
    let ws;
    
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem('token');
        const storedUser = localStorage.getItem('user');
        
        if (!token) {
          // No token, set as not authenticated
          if (isMounted) {
            setUser(null);
            setIsAuthenticated(false);
            setLoading(false);
            setIsInitialized(true);
          }
          return;
        }
        
        // Set the auth header
        api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
        
        // If we have a stored user, use it temporarily while we validate the token
        if (storedUser) {
          try {
            const parsedUser = JSON.parse(storedUser);
            if (isMounted) {
              setUser(parsedUser);
              setIsAuthenticated(true);
            }
          } catch (e) {
            console.error('Failed to parse stored user:', e);
          }
        }
        
        // Verify the token with the server
        try {
          let response;
          try {
            response = await api.get('/auth/me', { retry: 0, timeout: 5000 });
          } catch (meError) {
            console.log('Falling back to /profile endpoint');
            response = await api.get('/auth/profile', { retry: 0, timeout: 5000 });
          }
          
          if (isMounted) {
            const userData = response.data.user || response.data;
            localStorage.setItem('user', JSON.stringify(userData));
            setUser(userData);
            setIsAuthenticated(true);
            // Initialize WebSocket after successful auth
            ws = initWebSocket(token);
          }
        } catch (error) {
          console.error('Token validation failed:', error);
          if (error.response?.status !== 401) {
            console.error('Auth error:', error.message);
          }
          // Clear invalid auth data
          localStorage.removeItem('token');
          localStorage.removeItem('user');
          delete api.defaults.headers.common['Authorization'];
          if (isMounted) {
            setUser(null);
            setIsAuthenticated(false);
          }
        }
      } catch (error) {
        console.error('Auth check failed:', error);
        if (isMounted) {
          setUser(null);
          setIsAuthenticated(false);
        }
      } finally {
        if (isMounted) {
          setLoading(false);
          setIsInitialized(true);
        }
      }
    };

    checkAuth();
    
    return () => {
      isMounted = false;
      if (ws) {
        cleanupWebSocket(ws);
      }
    };
  }, [initWebSocket, cleanupWebSocket]);

  // Login function with enhanced error handling and rate limiting support
  const login = async (email, password) => {
    setLoading(true);
    setError(null);
  
    try {
      const response = await api.post('/auth/login', { email, password }, { 
        retry: 3,
        retryCount: 0
      });
      
      const { token, user } = response.data;
      
      if (!token || !user) {
        throw new Error('Invalid response from server: Missing token or user data');
      }
      
      // Store token in localStorage and set default Authorization header
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(user));
      api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      
      // Set user state and mark as authenticated
      setUser(user);
      setIsAuthenticated(true);
      
      // Initialize WebSocket
      const newSocket = initWebSocket(token);
      
      // Show success message
      toast.success('Successfully logged in!');
      
      // Navigate to dashboard after a short delay to ensure state is updated
      setTimeout(() => {
        navigate('/dashboard', { replace: true });
      }, 100);
      
      return { success: true };
    } catch (error) {
      let errorMessage = 'Login failed. Please check your credentials and try again.';
      
      if (error.response?.status === 429) {
        errorMessage = 'Too many login attempts. Please wait a moment and try again.';
      } else if (error.response?.data?.message) {
        errorMessage = error.response.data.message;
      } else if (error.message) {
        errorMessage = error.message;
      }
      
      console.error('Login error:', error);
      setError(errorMessage);
      toast.error(errorMessage);
      
      // Clear any invalid tokens
      localStorage.removeItem('token');
      delete api.defaults.headers.common['Authorization'];
      setIsAuthenticated(false);
      
      return { success: false, error: errorMessage };
    } finally {
      setLoading(false);
    }
  };

  // Register function with validation
  const register = async (userData) => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await api.post('/auth/register', userData);
      const { token, user } = response.data;
      
      localStorage.setItem('token', token);
      setUser(user);
      setIsAuthenticated(true);
      
      // Initialize WebSocket after successful registration
      initWebSocket(token);
      
      toast.success('Registration successful! Welcome to PulsePoint!');
      navigate('/dashboard'); // Navigate after successful registration
      return { success: true };
    } catch (error) {
      const errorMessage = error.response?.data?.message || 'Registration failed. Please try again.';
      setError(errorMessage);
      toast.error(errorMessage);
      return { 
        success: false, 
        message: errorMessage,
        errors: error.response?.data?.errors
      };
    } finally {
      setLoading(false);
    }
  };

  // Update profile function
  const updateProfile = async (userData) => {
    try {
      const response = await api.put('/auth/me', userData);
      setUser(prev => ({
        ...prev,
        ...response.data.user
      }));
      toast.success('Profile updated successfully!');
      return { success: true };
    } catch (error) {
      const errorMessage = error.response?.data?.message || 'Failed to update profile.';
      setError(errorMessage);
      toast.error(errorMessage);
      return { 
        success: false, 
        message: errorMessage,
        errors: error.response?.data?.errors
      };
    }
  };

  // Refresh token function
  const refreshToken = async () => {
    try {
      const response = await api.post('/auth/refresh-token');
      const { token, user: userData } = response.data;
      
      localStorage.setItem('token', token);
      setUser(userData);
      setIsAuthenticated(true);
      
      return { success: true, token };
    } catch (error) {
      console.error('Failed to refresh token:', error);
      logout();
      return { success: false };
    }
  };

  // Context value
  const value = {
    user,
    loading,
    error,
    socket,
    socketConnected,
    socketAuthenticated,
    isAuthenticated,
    login,
    logout,
    register,
    updateProfile,
    refreshToken,
    isInitialized,
    clearError: () => setError(null)
  };

  return (
    <AuthContext.Provider value={value}>
      {isInitialized ? children : null}
    </AuthContext.Provider>
  );
};

// Custom hook to use auth context
const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export { AuthContext, useAuth };
export default AuthContext;
